/// The spin-up and Sun-spin guards (Standard Code modes.transitions) and the spin-sign flip.
/// vectors: 64
/// - st: Modes (passed rec)
/// - mp: ModeParams (passed rec)
/// - sun_ok: bool (passed true or false)
/// - sun: real[1][3] (passed a plain number)
/// - dt: real[1] (passed a plain number)
/// - returns s: Modes (passed rec)
#[allow(clippy::too_many_arguments)]
pub fn spin_guards(st: Modes, mp: ModeParams, sun_ok: bool, sun: [f64; 3], dt: f64) -> Modes {
    let mut s: Modes = Modes::default();
    s = st;
    let mut d: f64 = (core::f64::consts::PI / 180.0);
    let mut wz: f64 = s.w_est[2];
    let mut wp: f64 = f64::sqrt(((s.w_est[0] * s.w_est[0]) + (s.w_est[1] * s.w_est[1])));
    if (rt::norm(s.w_est) > (mp.ss_omega_max_dps * d)) {
        s = crate::shared::modes_enter(s, 0);
    } else if (s.mode == 5) {
        let mut conv: bool = ((rt::fabs((wz - ((s.sigma * mp.ss_spin_dps) * d))) < (mp.ss_z_in_dps * d)) && (wp < (mp.ss_perp_in_dps * d)));
        if (conv && sun_ok) {
            s.sz_sum = (s.sz_sum + sun[2]);
            s.sz_n = (s.sz_n + 1);
        }
        if ((((s.t - s.sz_t0) >= mp.ss_t_check_s) && (s.sz_n > 0)) && ((s.sz_sum / (s.sz_n as f64)) > mp.ss_sun_min)) {
            s.sigma = (-(s.sigma));
            s.sz_sum = 0.0;
            s.sz_n = 0;
            s.sz_t0 = s.t;
        }
        let mut ok: bool = ((conv && sun_ok) && (sun[2] < 0.0));
        if ok {
            s.hold = (s.hold + dt);
        } else {
            s.hold = 0.0;
        }
        if (s.hold >= mp.ss_dwell_in_s) {
            s = crate::shared::modes_enter(s, 6);
        }
    } else {
        let mut bad: bool = ((rt::fabs(wz) < (mp.ss_omega_exit_dps * d)) || (wp > (mp.ss_perp_out_dps * d)));
        if bad {
            s.hold = (s.hold + dt);
        } else {
            s.hold = 0.0;
        }
        if (s.hold >= mp.ss_dwell_out_s) {
            s = crate::shared::modes_enter(s, 5);
        }
    }
    s
}

/// The transitions of one tick (after safe mode): the detumble exit, the spin guards, the
/// gyro-propagated Sun vector of the acquisition laws, the end of the rotor Sun acquisition.
/// vectors: 96
/// - st: Modes (passed rec)
/// - mp: ModeParams (passed rec)
/// - zw: real[1][3] (passed a plain number)
/// - sun_ok: bool (passed true or false)
/// - sun: real[1][3] (passed a plain number)
/// - dt: real[1] (passed a plain number)
/// - returns s: Modes (passed rec)
#[allow(clippy::too_many_arguments)]
pub fn modes_step(st: Modes, mp: ModeParams, zw: [f64; 3], sun_ok: bool, sun: [f64; 3], dt: f64) -> Modes {
    let mut s: Modes = Modes::default();
    s = st;
    if ((((s.mode == 0) || (s.mode == 7)) && (mp.auto_next != 255)) && ((s.faults & (256 | 512)) == 0)) {
        if (rt::norm(zw) < mp.detumble_exit) {
            s.hold = (s.hold + dt);
        } else {
            s.hold = 0.0;
        }
        if (s.hold >= mp.detumble_hold_s) {
            s = crate::shared::modes_enter(s, mp.auto_next);
        }
    }
    if (((s.mode == 5) || (s.mode == 6)) && (mp.ss_law != 2)) {
        s = crate::gdn::spin_guards(s, mp, sun_ok, sun, dt);
    }
    if (((s.mode == 5) || (s.mode == 6)) || (s.mode == 8)) {
        if sun_ok {
            s.s_prop = sun;
            s.s_prop_ok = true;
        } else if s.s_prop_ok {
            let mut a: [[f64; 3]; 3] = crate::gdn::dcm(crate::shared::fromrotvec(rt::vscale(s.w_est, dt)));
            s.s_prop = rt::unit(rt::mv(a, s.s_prop));
        }
    }
    if ((s.mode == 8) && (mp.auto_next != 255)) {
        let mut ok: bool = ((sun_ok && (f64::acos(rt::clamp(rt::dot(sun, mp.sun_axis), ((-(1)) as f64), 1.0)) < (mp.sa_done_deg * (core::f64::consts::PI / 180.0)))) && s.ad_ok);
        if ok {
            s.acq_hold = (s.acq_hold + dt);
        } else {
            s.acq_hold = 0.0;
        }
        if (s.acq_hold >= mp.sa_done_hold_s) {
            s = crate::shared::modes_enter(s, mp.auto_next);
        }
    }
    s
}

/// Commanded changes: every schedule entry whose time has come, in order.
/// vectors: 48
/// - st: Modes (passed rec)
/// - mp: ModeParams (passed rec)
/// - returns s: Modes (passed rec)
#[allow(clippy::too_many_arguments)]
pub fn modes_schedule(st: Modes, mp: ModeParams) -> Modes {
    let mut s: Modes = Modes::default();
    s = st;
    {
        let __end32: i64 = 8;
        let mut k: i64 = 0;
        while k < __end32 {
            if ((s.sched_i < mp.n_sched) && (s.t >= mp.sched_t[(s.sched_i) as usize])) {
                s = crate::shared::modes_enter(s, mp.sched_mode[(s.sched_i) as usize]);
                s.sched_i = (s.sched_i + 1);
            }
            k += 1;
        }
    }
    s
}

/// The nadir-family yaw flip with hysteresis h: turn 180 deg about the boresight when the power face
/// would look away from the Sun. Returns the new flip.
/// - r: real[m][3] (passed in m)
/// - v: real[m/s][3] (passed in m/s)
/// - q_off: real[1][4] (passed a plain number)
