/// - roll_axis: real[1][3] (passed a plain number)
/// - sun_eci: real[1][3] (passed a plain number)
/// - flip: bool (passed true or false)
/// - hyst: real[1] (passed a plain number)
/// - returns flip_out: bool (passed true or false)
#[allow(clippy::too_many_arguments)]
pub fn yaw_flip(r: [f64; 3], v: [f64; 3], q_off: [f64; 4], sun_axis: [f64; 3], roll_axis: [f64; 3], sun_eci: [f64; 3], flip: bool, hyst: f64) -> bool {
    let mut flip_out: bool = false;
    let mut z: [f64; 3] = [0.0; 3];
    let (mut q, mut w, mut wd) = crate::gdn::guidance(0, r, v, 0.0, q_off, 0.0, 0.0, 1.0, z, [0.0, 0.0, 0.0, 1.0], sun_axis, roll_axis, sun_eci, false);
    let mut sb: [f64; 3] = rt::mv(crate::gdn::dcm(q), rt::unit(sun_eci));
    let mut a: [f64; 3] = [0.0, 0.0, ((-(1)) as f64)];
    if (rt::norm(sun_axis) > 0.0) {
        a = rt::unit(sun_axis);
    }
    let mut d: f64 = rt::dot(a, sb);
    flip_out = flip;
    if (d < (-(hyst))) {
        flip_out = true;
    } else if (d > hyst) {
        flip_out = false;
    }
    flip_out
}
